package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * An invoice as the all-invoices list shows it: its own id, amount and lifecycle status plus the
 * NAME of the project it was raised against (not just the id), so the front-end renders the
 * cross-entity join without a second request. Built by the JPQL constructor expression in
 * {@link InvoiceRepository#findAllViews()}.
 */
public class InvoiceView {

    private final Long id;
    private final Long projectId;
    private final String projectName;
    private final BigDecimal amount;
    private final String status;

    public InvoiceView(Long id, Long projectId, String projectName, BigDecimal amount,
            String status) {
        this.id = id;
        this.projectId = projectId;
        this.projectName = projectName;
        this.amount = amount;
        this.status = status;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public String getProjectName() {
        return projectName;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public String getStatus() {
        return status;
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * (Spring beans are exposed to OfficeFloor by the rest-spring-boot starter).
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** Every invoice for one project, oldest id first — the shape a project's list renders. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /**
     * Every invoice across all projects with the NAME of the project it belongs to, oldest id
     * first — the shape the one all-invoices list renders.
     */
    @Query("SELECT new net.officefloor.hq.app.InvoiceView(i.id, i.projectId, p.name, i.amount, "
            + "i.status) FROM Invoice i, Project p WHERE i.projectId = p.id ORDER BY i.id ASC")
    List<InvoiceView> findAllViews();

    /**
     * Total amount still owed: the sum of every SENT-but-not-yet-paid invoice's amount across all
     * projects. Only invoices actually sent to the client count — DRAFT invoices are excluded
     * (they have not been billed yet) and PAID invoices are settled. COALESCE keeps it 0 (never
     * null) when nothing is outstanding — the dashboard's headline figure.
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'SENT'")
    BigDecimal sumOutstanding();
}

