1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import net.officefloor.server.http.HttpException;
5	import net.officefloor.server.http.HttpStatus;
6	import net.officefloor.web.HttpPathParameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * POST /api/invoices/{id}/payments — record a payment against an invoice from {amount, date} and
12	 * return the saved row (with its id). Wired by
13	 * {@code officefloor/rest/api/invoices/{id}/payments.POST.yml}. A payment needs an amount above zero
14	 * and a date; anything missing/invalid is rejected with 400 and an unknown invoice with 404.
15	 */
16	public class InvoicePaymentsPost {
17	
18	    public void service(@HttpPathParameter("id") String id, @RequestBody NewPayment body,
19	            InvoiceRepository invoices, PaymentRepository payments,
20	            ObjectResponse<Payment> response) {
21	        Long invoiceId = Long.valueOf(id);
22	        invoices.findById(invoiceId).orElseThrow(() -> new HttpException(HttpStatus.NOT_FOUND));
23	        BigDecimal amount = body.getAmount();
24	        String date = body.getDate();
25	        if (amount == null || amount.signum() <= 0 || date == null || date.isBlank()) {
26	            throw new HttpException(HttpStatus.BAD_REQUEST);
27	        }
28	        Payment payment = new Payment();
29	        payment.setInvoiceId(invoiceId);
30	        payment.setAmount(amount);
31	        payment.setDate(date.trim());
32	        response.send(payments.save(payment));
33	    }
34	}
